import{z as C,x as T,o as t,c as B,q as l,j as i,D as r,d as E,s as o,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"WebRTC 与 ICE","description":"","frontmatter":{"title":"WebRTC 与 ICE","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/webrtc-ice.md","filePath":"cs/webrtc-ice.md","lastUpdated":1791063341000}'),p={name:"cs/webrtc-ice.md"};function A(d,a,c,h,P,f){const s=T("Mermaid");return t(),B("div",null,[a[2]||(a[2]=l('<h1 id="webrtc-与-ice" tabindex="-1">WebRTC 与 ICE <a class="header-anchor" href="#webrtc-与-ice" aria-label="Permalink to &quot;WebRTC 与 ICE&quot;">​</a></h1><div class="epigraph"><p>浏览器直连音视频与数据：ICE 收集候选、连通性检查，选出能打通 NAT 的路径；媒体走 SRTP，信令另给。</p><footer>—— 据 RFC 8445 ICE；RFC 8825 WebRTC 概览整理</footer></div><p><a href="/cs/bittorrent-dht">BT</a>要发现对等，<a href="/cs/dhcp-nat">NAT</a>挡在直连中间，而<a href="/cs/bittorrent-dht">上一课</a>的发现不解决实时媒体的低延迟传输。缺口是 <strong>WebRTC + ICE</strong>：候选从哪来、怎么配对检查，以及与下一课 STUN/TURN 的分工。本课不把 STUN 消息格式写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>通话要低延迟，能直连就不该都压到服务器中继。WebRTC 给浏览器一组实时媒体 API；ICE 负责选路：收集 host（本机）、srflx（NAT 反射）、relay（中继）三类候选，两两配对发 STUN 绑定做连通性检查，同意一条路径。信令——SDP offer/answer 的交换——经你自己的 HTTPS 服务器，协议不规定实现。媒体走 DTLS-SRTP 加密。与 QUIC 对照：两者都跑在能穿 NAT 的 UDP 上；ICE 出现得更早，解决「选哪条路」而非「如何可靠传输」。</p><p>ICE 是两端协商，没有集中控制器，不要写成 SDN。</p><p><span class="marginnote">直觉类比：ICE 像约人见面先把所有可能的地址都报一遍——自己家、公司前台、快递代收点——然后挨个试哪个能通；host 是自家门牌，srflx 是 NAT 映射出的公网门牌，relay 是快递柜，最稳但总要绕一道。</span></p><p><span class="marginnote">RFC 8445。Trickle ICE 增量候选。本课钉对象。</span></p><h3 id="信令与媒体分离" tabindex="-1">信令与媒体分离 <a class="header-anchor" href="#信令与媒体分离" aria-label="Permalink to &quot;信令与媒体分离&quot;">​</a></h3><p>分离是设计要点：ICE 只管选出能通的候选，媒体尽量 P2P，失败才中继；但没有信令通道交换候选与 SDP，ICE 根本不能开始。对称 NAT 对不同目的地换端口，srflx 候选对不上号，常要 TURN 兜底。</p><p><span class="marginnote">术语翻译：srflx（server-reflexive）就是「路由器帮你转寄后露出公网的地址」——你向 STUN 服务器发个包，它回一句「我看到你来自 ip:port」，这个 ip:port 就是别人能找到你的外门牌。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>流程三步：收集候选、配对检查、选定路径。对照 SSH 转发：那是叠加在 TCP 上的隧道；ICE 尽量直连 UDP，中继是最后选项。与 MPTCP 对照：多候选在表面积上类似多径，但 ICE 选定后通常只留一条媒体路径。</p>',13)),(t(),i(n,null,{default:r(()=>[o(s,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20SIG%5B%22%E4%BF%A1%E4%BB%A4%20SDP%22%5D%20--%3E%20ICE%5B%22%E6%94%B6%E9%9B%86%E5%80%99%E9%80%89%22%5D%0A%20%20ICE%20--%3E%20CHK%5B%22%E8%BF%9E%E9%80%9A%E6%80%A7%E6%A3%80%E6%9F%A5%22%5D%0A%20%20CHK%20--%3E%20P2P%5B%22%E7%9B%B4%E8%BF%9E%E6%88%96%E4%B8%AD%E7%BB%A7%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"机制细节：对称 NAT 下连通性检查失败，转 TURN；企业防火墙禁 UDP 时走 TCP/TLS 中继，延迟明显抬升。拥塞控制在媒体栈内部——GCC 估带宽、NACK 重传——不是 TCP Reno 那一套。ICE 只管路径，精确时钟之类不需要。会话保持（Cookie 等）放在信令侧。",-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"为什么重要：中继一旦启用，媒体要绕道服务器，端到端延迟常从几十毫秒抬到上百毫秒，通话能听出「隔一层」的感觉；所以 ICE 把 relay 排在最后——能直连绝不中继。")],-1)),(t(),i(n,null,{default:r(()=>[o(s,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E5%80%99%E9%80%89%E9%85%8D%E5%AF%B9%E5%AE%8C%E6%88%90%22%5D%20--%3E%20T%7B%22host%20%E5%AF%B9%E8%83%BD%E9%80%9A%EF%BC%9F%22%7D%0A%20%20T%20--%3E%7C%22%E6%98%AF%22%7C%20P1%5B%22%E9%80%89%E7%9B%B4%E8%BF%9E%EF%BC%8C%E5%BB%B6%E8%BF%9F%E6%9C%80%E4%BD%8E%22%5D%0A%20%20T%20--%3E%7C%22%E5%90%A6%22%7C%20S%7B%22srflx%20%E5%AF%B9%E8%83%BD%E9%80%9A%EF%BC%9F%22%7D%0A%20%20S%20--%3E%7C%22%E6%98%AF%EF%BC%88%E6%99%AE%E9%80%9A%20NAT%EF%BC%89%22%7C%20P2%5B%22%E9%80%89%20NAT%20%E7%A9%BF%E9%80%8F%E7%9B%B4%E8%BF%9E%22%5D%0A%20%20S%20--%3E%7C%22%E5%90%A6%EF%BC%88%E5%AF%B9%E7%A7%B0%20NAT%20%2F%20%E7%A6%81%20UDP%EF%BC%89%22%7C%20P3%5B%22%E9%80%80%20TURN%20%E4%B8%AD%E7%BB%A7%EF%BC%8C%E5%BB%B6%E8%BF%9F%E6%8A%AC%E5%8D%87%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p>安全上，DTLS 指纹验证对端身份，防媒体注入；本课不写扫描与穿透操作。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 simulcast 的全部。STUN/TURN 是下一课。后课默认：ICE 负责选路，媒体尽量 P2P；没有信令通道，ICE 不能开始。</p><p>下一课<a href="/cs/stun-turn">STUN / TURN</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ICE 用候选配对与连通性检查穿过 NAT。</li><li>信令与媒体分离，信令通道自备。</li><li>直连失败才中继，延迟随之上升。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 8445；RFC 8825。</li></ul>',6))])}const D=C(p,[["render",A]]);export{m as __pageData,D as default};
